1	/**
2	 * Copyright (c) 2026 Huawei Technologies Co., Ltd.
3	 * This program is free software, you can redistribute it and/or modify it under the terms and conditions of
4	 * CANN Open Software License Agreement Version 2.0 (the "License").
5	 * Please refer to the License for details. You may not use this file except in compliance with the License.
6	 * THIS SOFTWARE IS PROVIDED ON AN "AS IS" BASIS, WITHOUT WARRANTIES OF ANY KIND, EITHER EXPRESS OR IMPLIED,
7	 * INCLUDING BUT NOT LIMITED TO NON-INFRINGEMENT, MERCHANTABILITY, OR FITNESS FOR A PARTICULAR PURPOSE.
8	 * See LICENSE in the root of the software repository for the full text of the License.
9	 */
10	
11	#include "kernel_operator.h"
12	#include "atvoss.h"
13	#include "example_common.h"
14	#include "command_line.h"
15	
16	static constexpr int32_t TILE_SIZE = 32;
17	static constexpr int32_t MAX_DIM = 8;
18	
19	template <typename T>
20	struct AbsConfig {
21	    using Dtype = T;
22	
23	    using TileShape = Atvoss::Shape<TILE_SIZE>;
24	    struct AbsCompute {
25	        template <template <typename> class Tensor>
26	        __host_aicore__ constexpr auto Compute() const
27	        {
28	            auto in = Atvoss::PlaceHolder<1, Tensor<Dtype>, Atvoss::ParamUsage::IN>();
29	            auto out = Atvoss::PlaceHolder<2, Tensor<Dtype>, Atvoss::ParamUsage::OUT>();
30	            return (out = Abs(in));
31	        };
32	    };
33	
34	    static constexpr Atvoss::Ele::DefaultBlockPolicy<TileShape> blockPolicy{TileShape{}};
35	
36	    static constexpr Atvoss::Ele::DefaultKernelPolicy kernelPolicy{Atvoss::Ele::DefaultSegmentPolicy::UniformSegment};
37	
38	    using ArchTag = Atvoss::Arch::DAV_3510;
39	
40	    using BlockOp = Atvoss::Ele::BlockBuilder<AbsCompute, ArchTag, blockPolicy, Atvoss::Ele::DefaultBlockConfig>;
41	
42	    using KernelOp = Atvoss::Ele::KernelBuilder<BlockOp, kernelPolicy>;
43	
44	    using DeviceOp = Atvoss::DeviceAdapter<KernelOp>;
45	};
46	
47	struct Options {
48	    // 存储解析后的值
49	    std::vector<int> shape;
50	    std::string typeInput;
51	    bool help;
52	
53	    // 默认构造：不解析，只设默认值
54	    Options() : shape({}), typeInput("f32"), help(false)
55	    {}
56	
57	    // 解析函数
58	    void parse(int argc, char const* argv[])
59	    {
60	        CommandLine cmd(argc, argv);
61	
62	        help = cmd.Present("help") || cmd.Present("h");
63	        shape = cmd.Get("shape", std::vector<int>{});
64	        typeInput = ToLower(cmd.Get("type_input", std::string("f32")));
65	
66	        validate(argv[0]);
67	    }
68	
69	    // 打印使用说明
70	    void PrintUsage(const char* progName = nullptr) const
71	    {
72	        if (!progName)
73	            progName = "program";
74	
75	        std::cout << "Usage: " << progName << " [options]\n"
76	                  << "\n"
77	                  << "Options:\n"
78	                  << "  --help                      Print this message\n"
79	                  << "  --shape=M,N,O,...           Tensor dimensions (e.g., --shape=4,3,224,224)\n"
80	                  << "  --type_input=TYPE           Input data type (f32; default: f32)\n"
81	                  << "\n"
82	                  << "Example:\n"
83	                  << "  " << progName << " --shape=512,256,128 --type_input=f32 \n";
84	    }
85	
86	private:
87	    static std::string ToLower(std::string s)
88	    {
89	        std::transform(s.begin(), s.end(), s.begin(), ::tolower);
90	        return s;
91	    }
92	
93	    void validate(const char* progName)
94	    {
95	        if (help) {
96	            return; // 帮助不需要验证
97	        }
98	
99	        if (shape.empty()) {
100	            std::cerr << "[ERROR] Missing required argument: --shape\n";
101	            PrintUsage(progName);
102	            exit(1);
103	        }
104	        if (shape.size() > MAX_DIM) {
105	            std::cerr << "[ERROR] Input shape max dim is 8, current shape dim is: " << shape.size() << "\n";
106	            PrintUsage(progName);
107	            exit(1);
108	        }
109	        for (int d : shape) {
110	            if (d < 0) {
111	                std::cerr << "[ERROR] Invalid dimension size: " << d << "\n";
112	                exit(1);
113	            }
114	        }
115	
116	        std::vector<std::string> validTypes = {"f32"};
117	        auto checkType = [&](const std::string& t, const char* name) {
118	            if (std::find(validTypes.begin(), validTypes.end(), t) == validTypes.end()) {
119	                std::cerr << "[ERROR] Invalid " << name << " type '" << t << "'\n";
120	                PrintUsage(progName);
121	                exit(1);
122	            }
123	        };
124	
125	        checkType(typeInput, "input");
126	    }
127	};
128	
129	template <typename T>
130	static void Run(const Options& options)
131	{
132	    // --- Step 1: ACL 初始化 ---
133	    CHECK_ACL_RET(aclInit(nullptr));
134	    auto finalizeGuard = ReleaseSource([]() { aclFinalize(); });
135	
136	    // --- Step 2: 设置 device ID ---
137	    const int32_t deviceId = 0;
138	    CHECK_ACL_RET(aclrtSetDevice(deviceId));
139	    auto deviceResetGuard = ReleaseSource([deviceId]() { aclrtResetDevice(deviceId); });
140	
141	    // --- Step 3: 创建 Context ---
142	    aclrtContext context = nullptr;
143	    CHECK_ACL_RET(aclrtCreateContext(&context, deviceId));
144	    auto contextDestroyGuard = ReleaseSource([context]() { aclrtDestroyContext(context); });
145	
146	    // --- Step 4: 创建 Stream ---
147	    aclrtStream stream = nullptr;
148	    CHECK_ACL_RET(aclrtCreateStream(&stream));
149	    auto streamDestroyGuard = ReleaseSource([stream]() { aclrtDestroyStream(stream); });
150	
151	    // --- Step 5: 分配输入/输出的Device内存 ---
152	    const auto& shape = options.shape;
153	    const size_t shapeSize = std::accumulate(shape.begin(), shape.end(), size_t{1}, std::multiplies<>{});
154	    const size_t inputSize = shapeSize * sizeof(T);
155	    const size_t outputSize = shapeSize * sizeof(T);
156	    void* rawInput = nullptr;
157	    CHECK_ACL_RET(aclrtMalloc(&rawInput, inputSize, ACL_MEM_MALLOC_HUGE_FIRST));
158	    auto inputFreeGuard = ReleaseSource([rawInput]() { aclrtFree(rawInput); });
159	    T* deviceInput = static_cast<T*>(rawInput);
160	
161	    void* rawOutput = nullptr;
162	    CHECK_ACL_RET(aclrtMalloc(&rawOutput, outputSize, ACL_MEM_MALLOC_HUGE_FIRST));
163	    auto outputFreeGuard = ReleaseSource([rawOutput]() { aclrtFree(rawOutput); });
164	    T* deviceOutput = static_cast<T*>(rawOutput);
165	
166	    // --- Step 6: Host -> Device 数据拷贝 ---
167	    std::vector<T> hostInput(shapeSize, static_cast<T>(-1.5F));
168	    CHECK_ACL_RET(aclrtMemcpy(deviceInput, inputSize, hostInput.data(), inputSize, ACL_MEMCPY_HOST_TO_DEVICE));
169	
170	    // --- Step 7: 构造参数信息 ---
171	    uint64_t shapeArray[MAX_DIM] = {0};
172	    std::copy(shape.begin(), shape.end(), shapeArray);
173	    Atvoss::Tensor<T> t1(deviceInput, shapeArray, shape.size());
174	    Atvoss::Tensor<T> t2(deviceOutput, shapeArray, shape.size());
175	    auto arguments = Atvoss::ArgumentsBuilder{}.inputOutput(t1, t2).build();
176	
177	    // --- Step 8: 执行算子 ---
178	    using DeviceOp = typename AbsConfig<T>::DeviceOp;
179	    DeviceOp deviceOp;
180	    deviceOp.Run(arguments, stream);
181	
182	    // --- Step 9: 同步并拷回结果 ---
183	    CHECK_ACL_RET(aclrtSynchronizeStream(stream));
184	    std::vector<T> hostOutput(shapeSize);
185	    CHECK_ACL_RET(aclrtMemcpy(hostOutput.data(), outputSize, deviceOutput, outputSize, ACL_MEMCPY_DEVICE_TO_HOST));
186	
187	    // --- Step 10: 验证结果 ---
188	    std::vector<T> golden(shapeSize, 1.5f);
189	    if (!VerifyResults(golden, hostOutput)) {
190	        std::cout << "Accuracy verification failed." << std::endl;
191	    } else {
192	        std::cout << "Accuracy verification passed." << std::endl;
193	    }
194	}
195	
196	int main(int argc, char const* argv[])
197	{
198	    Options options;
199	    options.parse(argc, argv);
200	
201	    if (options.help) {
202	        options.PrintUsage(argv[0]);
203	        return 0;
204	    }
205	
206	    // 继续执行计算逻辑...
207	    if (options.typeInput == "f32") {
208	        std::cout << "Start abs fp32 data" << std::endl;
209	        Run<float>(options);
210	    }
211	
212	    return 0;
213	}
214

